package cn.lili.common.security.session;
import cn.lili.modules.community.p0.support.*;
import com.google.gson.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfSystemProperty;
import java.time.*;
import java.util.*;
import static cn.lili.common.security.session.Stage1PersistenceTest.*;
import static cn.lili.modules.community.p0.support.Stage1Json.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

@EnabledIfSystemProperty(named="s1.integration",matches="owned-run")
@Timeout(value=8,unit=java.util.concurrent.TimeUnit.MINUTES)
class Stage1GoodsStateMatrixTest {
    @BeforeAll static void start()throws Exception{initialize();}
    @AfterAll static void end()throws Exception{finish();}
    @BeforeEach void refresh()throws Exception{new Stage1SupplyMatrixTest().refresh();}
    static String idOf(JsonObject result){return result.getAsJsonObject("goods").get("id").getAsString();}
    @Test void reviewStateMatrixCompetingDecisionsAndEveryActionReplayHaveOneDurableResult()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var row=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("MERCHANT_DELIVERY"),false);String id=idOf(row);var decision=map("requestId",req(),"expectedVersion",0,"contentVersion",0);
        call(post(Stage1Routes.MANAGER+"/goods/"+id+"/approve"),reviewer,decision,409);var submit=map("requestId",req(),"expectedVersion",0);var submitted=call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),submit,200);assertEquals(submitted,call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),submit,200));submit.put("expectedVersion",1);call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),submit,409);
        call(post(Stage1Routes.MANAGER+"/goods/"+id+"/reject"),reviewer,map("requestId",req(),"expectedVersion",1,"contentVersion",0,"reason","  "),422);
        var approve=map("requestId",req(),"expectedVersion",1,"contentVersion",0);var reject=map("requestId",req(),"expectedVersion",1,"contentVersion",0,"reason","S1_TEST竞争拒绝");var outcome=Stage1ConcurrencyTest.race(new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/goods/"+id+"/approve",reviewer,approve),new Stage1ConcurrencyTest.Command("POST",Stage1Routes.MANAGER+"/goods/"+id+"/reject",reviewer,reject));String action=outcome.get(0)==200?"approve":"reject";call(post(Stage1Routes.MANAGER+"/goods/"+id+"/"+action),reviewer,outcome.get(0)==200?approve:reject,200);assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_goods_review WHERE goods_id=? AND decision IN ('APPROVED','REJECTED')",id));call(post(Stage1Routes.MANAGER+"/goods/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",2,"contentVersion",0),409);
        if(outcome.get(0)!=200){row.getAsJsonObject("payload").addProperty("subtitle","S1_TEST驳回后实质修订");var saved=call(put(Stage1Routes.STORE+"/goods/"+id+"/content"),owner.login().session(),map("requestId",req(),"expectedVersion",2,"payload",row.get("payload")),200);call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),map("requestId",req(),"expectedVersion",3),200);call(post(Stage1Routes.MANAGER+"/goods/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",4,"contentVersion",1),200);}
        for(String next:List.of("list","unlist")){long version=db.count("SELECT version FROM li_p0_goods_control WHERE goods_id=?",id);var body=map("requestId",req(),"expectedVersion",version);var result=call(post(Stage1Routes.STORE+"/goods/"+id+"/"+next),owner.login().session(),body,200);assertEquals(result,call(post(Stage1Routes.STORE+"/goods/"+id+"/"+next),owner.login().session(),body,200));body.put("expectedVersion",version+1);call(post(Stage1Routes.STORE+"/goods/"+id+"/"+next),owner.login().session(),body,409);assertEquals(version+1,db.count("SELECT version FROM li_p0_goods_control WHERE goods_id=?",id));}
        var history=db.rows("SELECT * FROM li_p0_goods_review WHERE goods_id=?",id);var inventory=db.rows("SELECT * FROM li_p0_inventory_adjustment WHERE store_id=?",owner.store());var skuIds=db.rows("SELECT id FROM li_goods_sku WHERE goods_id=? ORDER BY id",id);
        for(int i=0;i<2;i++)for(String next:List.of("force-off","release")){long v=db.count("SELECT version FROM li_p0_goods_control WHERE goods_id=?",id);call(post(Stage1Routes.MANAGER+"/goods/"+id+"/"+next),operator,map("requestId",req(),"expectedVersion",v,"reason","  "),422);call(post(Stage1Routes.MANAGER+"/goods/"+id+"/"+next),operator,map("requestId",req(),"expectedVersion",v,"reason","S1_TEST监管历史"),200);assertEquals("DOWN",db.required("SELECT market_enable FROM li_goods WHERE id=?",id).get("market_enable"));}assertEquals(history,db.rows("SELECT * FROM li_p0_goods_review WHERE goods_id=?",id));assertEquals(inventory,db.rows("SELECT * FROM li_p0_inventory_adjustment WHERE store_id=?",owner.store()));assertEquals(skuIds,db.rows("SELECT id FROM li_goods_sku WHERE goods_id=? ORDER BY id",id));
    }
    @Test void everyCriticalContentChangeUnlistsAndPreservesIndependentStockAndCost()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();String originalCategory=category;
        for(String change:List.of("name","gallery","detail","price","specification","method","category")){
            category=originalCategory;var created=Stage1SupplyMatrixTest.createGoods(owner,5,List.of("MERCHANT_DELIVERY"),true);String id=idOf(created);var before=db.required("SELECT quantity,cost FROM li_goods_sku WHERE goods_id=?",id);var payload=created.getAsJsonObject("payload").deepCopy();
            switch(change){case "category"->{String leaf=Stage1BusinessBoundaryTest.category(originalCategory,"S1_TEST新叶类目",0,200).get("id").getAsString();call(post(Stage1Routes.MANAGER+"/categories/"+leaf+"/enable"),operator,map("requestId",req(),"expectedVersion",0,"reason","S1_TEST类目变更"),200);payload.addProperty("categoryId",leaf);}case "name"->payload.addProperty("name","S1_TEST关键名称");case "gallery"->payload.add("galleryFileIds",new Gson().toJsonTree(List.of(upload(owner.login().session(),Stage1Routes.STORE,"GOODS"))));case "detail"->payload.add("detailBlocks",new Gson().toJsonTree(List.of(map("type","text","text","S1_TEST详情修改"))));case "price"->payload.getAsJsonArray("skus").get(0).getAsJsonObject().addProperty("priceCent",9999);case "specification"->{var sku=payload.getAsJsonArray("skus").get(0).getAsJsonObject();sku.add("specifications",new Gson().toJsonTree(List.of(map("name","规格","value","新款"))));call(put(Stage1Routes.STORE+"/goods/"+id+"/content"),owner.login().session(),map("requestId",req(),"expectedVersion",3,"payload",payload,"confirmUnlist",true),409);sku.remove("id");sku.addProperty("code","NEW_"+db.id());sku.addProperty("initialQuantity",0);sku.addProperty("costCent",0);}case "method"->{String point=createPointFixture(owner,"COMMUNITY_PICKUP");call(post(Stage1Routes.STORE+"/points/"+point+"/enable"),owner.login().session(),map("requestId",req(),"expectedVersion",0,"reason","S1_TEST方式"),200);payload.add("methods",new Gson().toJsonTree(List.of("COMMUNITY_PICKUP")));}}
            var saved=call(put(Stage1Routes.STORE+"/goods/"+id+"/content"),owner.login().session(),map("requestId",req(),"expectedVersion",3,"payload",payload,"confirmUnlist",true),200);assertEquals("DOWN",saved.getAsJsonObject("goods").get("marketStatus").getAsString());assertEquals("DRAFT",saved.getAsJsonObject("goods").get("reviewStatus").getAsString());assertEquals(1,saved.getAsJsonObject("goods").get("contentVersion").getAsInt());String oldSku=Stage1CrossHostTest.sku(created);assertEquals(before,db.required("SELECT quantity,cost FROM li_goods_sku WHERE id=?",oldSku));assertEquals(1,db.count("SELECT COUNT(*) FROM li_p0_goods_review WHERE goods_id=?",id));if(change.equals("specification"))assertEquals(0,db.count("SELECT enabled FROM li_p0_sku_control WHERE sku_id=?",oldSku));
        }
    }
    @Test void twoSkuAvailabilityImageFallbackAndCurrentReadMatrixNeverHideAValidAlternative()throws Exception{
        var owner=Stage1SupplyMatrixTest.ready();var payload=object(goodsPayload(unitFixture(),upload(owner.login().session(),Stage1Routes.STORE,"GOODS"),0));var one=payload.getAsJsonArray("skus").get(0).getAsJsonObject();one.add("specifications",new Gson().toJsonTree(List.of(map("name","款式","value","无货"))));var two=one.deepCopy();two.addProperty("code","ALT_"+db.id());two.addProperty("initialQuantity",5);two.add("specifications",new Gson().toJsonTree(List.of(map("name","款式","value","有货"))));payload.getAsJsonArray("skus").add(two);var goods=call(post(Stage1Routes.STORE+"/goods"),owner.login().session(),map("requestId",req(),"payload",payload),200);String id=idOf(goods);call(post(Stage1Routes.STORE+"/goods/"+id+"/submit"),owner.login().session(),map("requestId",req(),"expectedVersion",0),200);call(post(Stage1Routes.MANAGER+"/goods/"+id+"/approve"),reviewer,map("requestId",req(),"expectedVersion",1,"contentVersion",0),200);call(post(Stage1Routes.STORE+"/goods/"+id+"/list"),owner.login().session(),map("requestId",req(),"expectedVersion",2),200);var buyer=Stage1CrossHostTest.resident();String zero=goods.getAsJsonArray("skus").get(0).getAsJsonObject().get("id").getAsString(),stock=goods.getAsJsonArray("skus").get(1).getAsJsonObject().get("id").getAsString();
        assertEquals("BLOCKED",Stage1CrossHostTest.precheck(owner,buyer,zero,"MERCHANT_DELIVERY",null,true).get("status").getAsString());assertEquals("PASS",Stage1CrossHostTest.precheck(owner,buyer,stock,"MERCHANT_DELIVERY",null,true).get("status").getAsString());assertEquals(db.required("SELECT original FROM li_goods WHERE id=?",id).get("original"),db.required("SELECT original FROM li_goods_sku WHERE id=?",stock).get("original"));
        for(String kind:List.of("zeroDisabled","allDisabled","allZero","notApproved","unlisted","regulated")){
            String sql=switch(kind){case "zeroDisabled"->"UPDATE li_p0_sku_control SET enabled=0 WHERE sku_id="+zero;case "allDisabled"->"UPDATE li_p0_sku_control SET enabled=0 WHERE goods_id="+id;case "allZero"->"UPDATE li_goods_sku SET quantity=0 WHERE goods_id="+id;case "notApproved"->"UPDATE li_p0_goods_control SET review_status='DRAFT' WHERE goods_id="+id;case "unlisted"->"UPDATE li_goods SET market_enable='DOWN' WHERE id="+id;default->"UPDATE li_p0_goods_control SET forced_off=1 WHERE goods_id="+id;};
            try{db.update(sql);var list=call(get(Stage1Routes.BUYER+"/stores/"+owner.store()+"/goods"),buyer,null,200);var detail=call(get(Stage1Routes.BUYER+"/goods/"+id),buyer,null,200);boolean available=kind.equals("zeroDisabled");assertEquals(available,detail.get("available").getAsBoolean(),kind);assertEquals(available?1:0,list.get("total").getAsInt(),kind);assertFalse(detail.toString().contains("costCent"));}finally{db.update("UPDATE li_p0_sku_control SET enabled=1 WHERE goods_id=?",id);db.update("UPDATE li_goods_sku SET quantity=5 WHERE id=?",stock);db.update("UPDATE li_p0_goods_control SET review_status='APPROVED',forced_off=0 WHERE goods_id=?",id);db.update("UPDATE li_goods SET market_enable='UPPER' WHERE id=?",id);}
        }
    }
}
